async fireTest(p: CompiledPredicate, fireFixtures: FireFixture[]): Promise<FireTestResult> {
  if (!this.battery.some((b) => b.id === p.id)) {
    console.warn(`[calibration] fireTest called for predicate ${p.id} not in the battery — verdict will be recorded but predicate won't appear in liveBattery()/excluded()`);
  }
  const result = this.computeFireTest(p, fireFixtures);
  this.fireByPred.set(p.id, result);
  this.mark(p);
  return result;
}

